"use client";

import { useEffect, useRef } from "react";

// Generated by whos.amung.us/getstarted/ for this homepage.
export const visitorWidgetId = "d0mhfgjao9";
const slotId = "hengyuvisitors";

type VisitorWindow = Window & {
  _wau?: (string[])[];
  _wau_opt?: { target: string; fbase: boolean };
};

export default function VisitorMap() {
  const container = useRef<HTMLDivElement>(null);
  const initialized = useRef(false);

  useEffect(() => {
    if (initialized.current || !container.current) return;
    initialized.current = true;
    const visitorWindow = window as VisitorWindow;
    visitorWindow._wau = visitorWindow._wau || [];
    visitorWindow._wau_opt = { target: "_blank", fbase: true };
    visitorWindow._wau.push(["map", visitorWidgetId, slotId, "320", "160", "classic", "default-blue"]);
    const script = document.createElement("script");
    script.src = "https://waust.at/m.js";
    script.async = true;
    container.current.appendChild(script);
  }, []);

  return (
    <section className="visitor-section" aria-labelledby="visitors-title">
      <h2 id="visitors-title">Visitors</h2>
      <div className="visitor-map" ref={container} aria-label="World map of visitor locations">
        <span id={`_wau${slotId}`} />
      </div>
      <a className="visitor-stats" href={`https://whos.amung.us/stats/maps/${visitorWidgetId}/`} target="_blank" rel="noreferrer">View visitor locations</a>
    </section>
  );
}
